def solve(text):
    result = []
    field = []
    in_quote = False
    i = 0
    n = len(text)

    while i < n:
        char = text[i]

        if not in_quote:
            if char == '"':
                in_quote = True
                i += 1
                continue
            elif char == ',':
                if field:
                    result.append(''.join(field))
                    field = []
                i += 1
                continue
            else:
                field.append(char)
                i += 1
        else:
            if char == '"':
                # Check if it's escaped
                if i < n - 1 and text[i+1] == '"':
                    field.append('"')
                    i += 2
                else:
                    in_quote = False
                    i += 1
                    if field:
                        result.append(''.join(field))
                        field = []
            else:
                field.append(char)
                i += 1

    # Handle the last field if it exists
    if field:
        result.append(''.join(field))

    # Validate the record
    if in_quote:
        return None

    # Check for extra comma or content after closing quote
    for j in range(len(result)):
        if result[j]:
            continue
        else:
            return None

    return result
