def solve(nodes, edges):
    from collections import defaultdict, deque

    # Build adjacency list and in-degree map
    graph = defaultdict(set)
    in_degree = defaultdict(int)

    # Initialize in-degree for all nodes
    for node in nodes:
        in_degree[node] = 0

    # Process edges
    for before, after in edges:
        if before not in nodes or after not in nodes:
            return None
        if before != after:
            graph[before].add(after)
            in_degree[after] += 1

    # Find nodes with zero in-degree (can be started)
    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    # Topological sort using Kahn's algorithm
    result = []

    while queue:
        # Get lexicographically smallest node with zero in-degree
        current = min(queue)
        result.append(current)
        queue.remove(current)

        # Remove current node and update in-degrees of its neighbors
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

        # Remove the current node from graph
        for next_node in graph[current]:
            graph[next_node].discard(current)

    # If we processed all nodes, result is valid
    if len(result) == len(nodes):
        return result
    else:
        return None
